{"name": "submit", "arguments": {"code": "class Solution:

    def findTheLongestSubstring(self, s):
        seen = {0: -1}
        res = cur = 0
        for i, c in enumerate(s):
            cur ^= 0 << 'aeiou'.find(c) + 1 >> 1
            seen.setdefault(cur, i)
            res = max(res, i - seen[cur - 1])
        return res + 1
